// Prepara la petición al modelo de visión de Anthropic
const body = $input.first().json.body || $input.first().json;
const dataUrl = body.imagen || '';
const nivel = body.nivel === 'profesional' ? 'profesional' : 'sencillo';

const match = dataUrl.match(/^data:(image\/(?:jpeg|png|webp));base64,(.+)$/s);
if (!match) {
  throw new Error('Imagen no válida: se esperaba un dataURL base64 (jpeg/png/webp)');
}
const mediaType = match[1];
const base64 = match[2];

const sistemaBase = `Eres el asistente de valoración visual de la Clínica Dental Sonrisa. Analizas fotografías de bocas/dientes enviadas por pacientes y das una PRIMERA VALORACIÓN ORIENTATIVA, nunca un diagnóstico.\n\nReglas obligatorias:\n- Si la imagen NO muestra una boca/dientes o la calidad impide valorarla, dilo y pide una foto mejor (buena luz, boca abierta, enfocada). No inventes hallazgos.\n- Describe solo lo visible: higiene/placa/sarro aparente, estado aparente de encías, alineación, desgastes, manchas, posibles lesiones visibles. Usa lenguaje de probabilidad ('se aprecia', 'compatible con', 'podría'), nunca afirmaciones diagnósticas.\n- No prescribas medicamentos ni tratamientos concretos.\n- Indica una orientación de urgencia: sin signos de alarma / conviene revisión / conviene revisión pronto.\n- Cierra siempre recomendando confirmación con un odontólogo (primera consulta gratuita en la clínica).\n- Responde en español, en el formato: **Lo que se aprecia en la foto:** (lista), **¿Es urgente?**, **Siguiente paso:**. Máximo ~200 palabras.`;

const nivelInstr = nivel === 'profesional'
  ? 'NIVEL: PROFESIONAL. Usa terminología clínica odontológica (nomenclatura FDI si identificas piezas, gingivitis/periodontitis, tartrectomía, lesiones cariosas, etc.), como un informe entre colegas.'
  : 'NIVEL: SENCILLO. Explica como a un paciente sin conocimientos, sin tecnicismos, con tono cercano y tranquilizador.';

return [{
  json: {
    payload: {
      model: 'claude-opus-5',
      max_tokens: 1024,
      system: sistemaBase + '\n\n' + nivelInstr,
      messages: [{
        role: 'user',
        content: [
          { type: 'image', source: { type: 'base64', media_type: mediaType, data: base64 } },
          { type: 'text', text: 'Valora esta fotografía dental según tus instrucciones.' }
        ]
      }]
    }
  }
}];

// Extrae el texto de la respuesta del modelo
const r = $input.first().json;
if (r.stop_reason === 'refusal') {
  return [{ json: { resultado: '**No se ha podido analizar esta imagen.** Prueba con otra fotografía de tus dientes con buena luz.' } }];
}
const texto = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
return [{ json: { resultado: texto || 'No se recibió respuesta del análisis.' } }];
